import os
from typing import Dict, List, Any, Optional
from mindee import Client
from mindee.input import LocalInputSource
from mindee.products import InvoiceV4

def validate_structured_extraction(
    document_path: str,
    required_fields: List[str],
    confidence_threshold: float = 0.8,
    api_key: Optional[str] = None
) -> Dict[str, Any]:
    """
    Validates required structured fields and their confidence scores using 
    Mindee's hosted AI Document API for Invoice processing.
    """
    api_key = api_key or os.getenv("MINDEE_API_KEY")
    if not api_key:
        raise ValueError("Mindee API key is required. Pass it explicitly or set MINDEE_API_KEY environment variable.")

    if not os.path.exists(document_path):
        raise FileNotFoundError(f"Document not found: {document_path}")

    client = Client(api_key=api_key)
    input_source = LocalInputSource(file_path=document_path)

    response = client.parse(input_source, InvoiceV4)
    prediction = response.document.inference.prediction

    field_extractors = {
        "invoice_number": lambda p: (p.invoice_number.value, p.invoice_number.confidence),
        "date": lambda p: (p.date.value, p.date.confidence),
        "total_amount": lambda p: (p.total_amount.value, p.total_amount.confidence),
        "total_tax": lambda p: (p.total_tax.value, p.total_tax.confidence),
    }

    report = {
        "is_valid": True,
        "extracted_data": {},
        "missing_fields": [],
        "low_confidence_fields": []
    }

    for field_name in required_fields:
        if field_name not in field_extractors:
            raise ValueError(f"Unsupported field: '{field_name}'. Supported fields: {list(field_extractors.keys())}")

        extractor = field_extractors[field_name]
        try:
            value, confidence = extractor(prediction)
        except AttributeError as e:
            raise RuntimeError(f"Extraction failed for '{field_name}': {e}")

        if value is None:
            report["is_valid"] = False
            report["missing_fields"].append(field_name)
        else:
            report["extracted_data"][field_name] = {
                "value": value,
                "confidence": round(confidence, 4)
            }
            if confidence < confidence_threshold:
                report["is_valid"] = False
                report["low_confidence_fields"].append(field_name)

    return report
